{"content":"extends Node3D
## WorldManager - autoload. Owns all three realms, the chunk pipeline
## (generation threads -> main-thread meshing), block edits, spawn selection,
## time/weather and per-realm ambient conditions.

signal block_changed(realm: int, pos: Vector3i, old_id: int, new_id: int)
signal player_ready(player: Node)

const SAVE_VERSION := 1

## ---- Realm metadata ----
const REALMS := {
	WorldGenerator.Realm.OVERWORLD: {
		"name": "Overworld", "gravity": 29.4, "base_temp": 20.0,
		"sky": Color(0.45, 0.65, 0.9), "fog_dist": 260.0, "seed_shift": 0,
		"day_length": 60.0,
	},
	WorldGenerator.Realm.NETHER: {
		"name": "Nether", "gravity": 29.4, "base_temp": 45.0,
		"sky": Color(0.25, 0.05, 0.08), "fog_dist": 90.0, "seed_shift": 1_000_000,
		"day_length": 0.0,
	},
	WorldGenerator.Realm.HEAVEN: {
		"name": "Heaven", "gravity": 9.8, "base_temp": 22.0,
		"sky": Color(0.85, 0.9, 1.0), "fog_dist": 360.0, "seed_shift": 2_000_000,
		"day_length": 120.0,
	},
}

var seed_world := 1337

var generators := {}
var chunk_data: Dictionary = {}      # realm -> {Vector2i: ChunkData}
var chunk_queued: Dictionary = {}    # realm -> {Vector2i: bool}
var chunk_nodes: Dictionary = {}     # realm -> {Vector2i: Node3D}
var realm_roots := {}
var active_realm := WorldGenerator.Realm.OVERWORLD
var chunk_man: ChunkManager

var mats := {}
var time_of_day := 0.35
var _pump_budget_frac := 0.5
var _fall_timer := 0.0
var _fall_interval := 0.25
var spawn_position := Vector3.ZERO
var spawn_found := false

var _last_player_center := Vector2i(9999, 9999)
var _edit_queue: Array = []          # pending edits applied on main thread (networking)

var max_render_dist := 6             # chunks; mobile-friendly default
var _event_bus: Node


func _ready() -> void:
	_event_bus = get_node_or_null("/root/EventBus")
	for realm_id in REALMS:
		var gen := WorldGenerator.new(realm_id, seed_world + REALMS[realm_id].seed_shift)
		generators[realm_id] = gen
		chunk_data[realm_id] = {}
		chunk_queued[realm_id] = {}
		chunk_nodes[realm_id] = {}
		var root := Node3D.new()
		root.name = "Realm_%d" % realm_id
		add_child(root)
		realm_roots[realm_id] = root
	chunk_man = ChunkManager.new()
	chunk_man.name = "ChunkManager"
	chunk_man.world = self
	add_child(chunk_man)
	_build_materials()
	_find_spawn_later()


func _build_materials() -> void:
	var m_opaque := StandardMaterial3D.new()
	m_opaque.vertex_color_use_as_albedo = true
	m_opaque.roughness = 0.9
	m_opaque.metallic = 0.02
	mats["opaque"] = m_opaque
	var m_water := StandardMaterial3D.new()
	m_water.vertex_color_use_as_albedo = true
	m_water.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	m_water.roughness = 0.2
	m_water.metallic = 0.0
	mats["water"] = m_water
	var m_emissive := StandardMaterial3D.new()
	m_emissive.vertex_color_use_as_albedo = true
	m_emissive.emission_enabled = true
	m_emissive.emission = Color(1.0, 1.0, 1.0)
	m_emissive.emission_energy_multiplier = 0.6
	m_emissive.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	mats["emissive"] = m_emissive


func _find_spawn_later() -> void:
	call_deferred("_find_spawn")


func _find_spawn() -> void:
	var sv := SpawnValidator.new(generators[WorldGenerator.Realm.OVERWORLD])
	var spot := sv.find_spawn()
	if spot != Vector3.ZERO:
		spawn_position = Vector3(spot.x + 0.5, spot.y + 1.0, spot.z + 0.5)
		spawn_found = true
		# Guarantee a flat, solid 5x5 pad under the exact spawn point.
		for dx in range(-2, 3):
			for dz in range(-2, 3):
				var gy := floori(sv.gen.biome_gen.terrain_height(spot.x + dx, spot.z + dz))
				for fill_y in range(gy - 2, gy + 1):
					if fill_y <= 0:
						continue
					_set_block_inst(WorldGenerator.Realm.OVERWORLD,
						Vector3i(spot.x + dx, fill_y, spot.z + dz), BlockRegistry.Block.STONE, 0)
				_set_block_inst(WorldGenerator.Realm.OVERWORLD,
					Vector3i(spot.x + dx, gy + 1, spot.z + dz), BlockRegistry.Block.AIR, 0)
	else:
		spawn_position = Vector3(8.5, 60.0, 8.5)


## Generator access is read-only from worker threads after _ready.
func generator_for(realm: int) -> WorldGenerator:
	return generators[realm]


func realm_meta(realm: int) -> Dictionary:
	return REALMS.get(realm, REALMS[WorldGenerator.Realm.OVERWORLD])


func active_generator() -> WorldGenerator:
	return generators[active_realm]


func has_chunk_data(realm: int, cpos: Vector2i) -> bool:
	return chunk_data[realm].has(cpos)


func is_chunk_queued(realm: int, cpos: Vector2i) -> bool:
	return chunk_queued[realm].get(cpos, false) or chunk_data[realm].has(cpos)


func mark_chunk_queued(realm: int, cpos: Vector2i) -> void:
	chunk_queued[realm][cpos] = true


## Called from worker threads. Thread-safe handoff queue.
func on_chunk_data_ready(realm: int, cpos: Vector2i, data: ChunkData) -> void:
	chunk_man._mutex.lock()
	chunk_man._ready_data.append({"realm": realm, "pos": cpos, "data": data})
	chunk_man._mutex.unlock()


func _physics_process(delta: float) -> void:
	_process_pipeline(delta)
	_update_falling(delta)


func _process_pipeline(_delta: float) -> void:
	var player := get_tree().get_first_node_in_group("player")
	var center := Vector2i.ZERO
	if player != null and is_instance_valid(player):
		center = ChunkData.to_chunk(Vector3i(floori(player.global_position.x), 0, floori(player.global_position.z)))
	else:
		if spawn_found:
			center = ChunkData.to_chunk(Vector3i(floori(spawn_position.x), 0, floori(spawn_position.z)))
	# Load zone around player (active realm only).
	chunk_man.request_chunks(active_realm, center, max_render_dist)
	# Drain finished generation jobs.
	var pending: Array = []
	chunk_man._mutex.lock()
	pending = chunk_man._ready_data.duplicate()
	chunk_man._ready_data.clear()
	chunk_man._mutex.unlock()
	for item in pending:
		_install_chunk(item.realm, item.pos, item.data)


## Main thread: store + validate + mesh.
func _install_chunk(realm: int, cpos: Vector2i, data: ChunkData) -> void:
	chunk_data[realm][cpos] = data
	# Validators: structural support + cut-ore sweep.
	var validator := WorldValidator.new()
	var stats := validator.validate_support(data)
	validator.validate_no_cut_ores(data)
	if not stats.removed.is_empty() or not stats.cut_ores.is_empty():
		pass
	_try_mesh_chunk(realm, cpos)


func _neighbors_present(realm: int, cpos: Vector2i) -> bool:
	for dx in range(-1, 2):
		for dz in range(-1, 2):
			if not chunk_data[realm].has(cpos + Vector2i(dx, dz)):
				return false
	return true


func _try_mesh_chunk(realm: int, cpos: Vector2i) -> void:
	if not has_chunk_data(realm, cpos):
		return
	if not _neighbors_present(realm, cpos):
		return
	var data: ChunkData = chunk_data[realm][cpos]
	if data.meshed:
		return
	var mesher := ChunkMesher.new()
	var getter := Callable(self, "get_block_global").bind(realm)
	mesher.generate(data, getter)
	_apply_chunk_mesh(realm, cpos, mesher)
	data.meshed = true
	data.dirty = true
	chunk_man.stats.meshed += 1


func _apply_chunk_mesh(realm: int, cpos: Vector2i, mesher: ChunkMesher) -> void:
	var root: Node3D = chunk_nodes[realm].get(cpos)
	if root == null:
		root = Node3D.new()
		root.name = "Chunk_%d_%d" % [cpos.x, cpos.y]
		root.position = Vector3(cpos.x * ChunkData.CHUNK_X, 0, cpos.y * ChunkData.CHUNK_Z)
		realm_roots[realm].add_child(root)
		chunk_nodes[realm][cpos] = root
	# Visual surfaces.
	var mesh := ArrayMesh.new()
	var surf_to_mat := []  # material index per added surface
	for s in ChunkMesher.SURFACE_COUNT:
		if mesher.verts[s].is_empty():
			continue
		var arrays := []
		arrays.resize(Mesh.ARRAY_MAX)
		arrays[Mesh.ARRAY_VERTEX] = mesher.verts[s]
		arrays[Mesh.ARRAY_NORMAL] = mesher.normals[s]
		arrays[Mesh.ARRAY_COLOR] = mesher.colors[s]
		arrays[Mesh.ARRAY_INDEX] = mesher.indices[s]
		mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arrays)
		surf_to_mat.append(s)
	var mi: MeshInstance3D = root.get_node_or_null("Mesh")
	if mi == null:
		mi = MeshInstance3D.new()
		mi.name = "Mesh"
		root.add_child(mi)
	mi.mesh = mesh
	mi.material_overlay = null
	for i in surf_to_mat.size():
		var mat_name := "opaque"
		var s := surf_to_mat[i]
		if s == ChunkMesher.M_WATER:
			mat_name = "water"
		elif s == ChunkMesher.M_EMISSIVE:
			mat_name = "emissive"
		mi.set_surface_override_material(i, mats[mat_name])
	# Collision body.
	var body: StaticBody3D = root.get_node_or_null("Body")
	if body != null:
		body.free()
	if mesher.collision_vertices.size() >= 3:
		body = StaticBody3D.new()
		body.name = "Body"
		var shape := ConcavePolygonShape3D.new()
		shape.set_faces(mesher.collision_vertices)
		var col := CollisionShape3D.new()
		col.shape = shape
		body.add_child(col)
		body.collision_layer = 1 | 2 | 4
		body.collision_mask = 1 | 2 | 4
		root.add_child(body)


## ---- Global voxel reads ----

func get_block_global(realm: int, gx: int, gy: int, gz: int) -> int:
	if gy >= ChunkData.CHUNK_Y:
		return BlockRegistry.Block.AIR
	if gy < 0:
		gx = 0  # below world is always bedrock
		gy = 0
		gz = 0
		return BlockRegistry.Block.BEDROCK
	var cpos := ChunkData.to_chunk(Vector3i(gx, 0, gz))
	var data: ChunkData = chunk_data[realm].get(cpos)
	if data == null:
		return BlockRegistry.Block.AIR
	var lp := ChunkData.to_local(Vector3i(gx, gy, gz))
	return data.get_block(lp.x, gy, lp.z)


func get_meta_global(realm: int, gx: int, gy: int, gz: int) -> int:
	if gy >= ChunkData.CHUNK_Y or gy < 0:
		return 0
	var cpos := ChunkData.to_chunk(Vector3i(gx, 0, gz))
	var data: ChunkData = chunk_data[realm].get(cpos)
	if data == null:
		return 0
	var lp := ChunkData.to_local(Vector3i(gx, gy, gz))
	return data.get_meta(lp.x, gy, lp.z)


func surface_height(gx: int, gz: int) -> int:
	return generators[active_realm].surface_height(gx, gz)


## ---- Player edit API (authoritative, main thread) ----

func set_block(realm: int, pos: Vector3i, id: int, meta: int = 0) -> void:
	if NetworkManager.is_online():
		var remote: bool = network_world_edits
		if remote:
			NetworkManager.rpc_block_edit(pos, id, meta, realm)
	_set_block_inst(realm, pos, id, meta)
	block_changed.emit(realm, pos, get_block_global(realm, pos.x, pos.y, pos.z) if false else id, id)


var network_world_edits := true


func apply_remote_block(pos: Vector3i, id: int, meta: int, realm: int) -> void:
	_set_block_inst(realm, pos, id, meta)


func _set_block_inst(realm: int, pos: Vector3i, id: int, meta: int) -> void:
	if pos.y < 0 or pos.y >= ChunkData.CHUNK_Y:
		return
	var cpos := ChunkData.to_chunk(pos)
	var data: ChunkData = chunk_data[realm].get(cpos)
	if data == null:
		return
	var lp := ChunkData.to_local(pos)
	var old := data.get_block(lp.x, pos.y, lp.z)
	if old == id:
		data.set_meta(lp.x, pos.y, lp.z, meta)
		return
	data.set_block(lp.x, pos.y, lp.z, id)
	data.set_meta(lp.x, pos.y, lp.z, meta)
	data.meshed = false
	data.dirty = true
	_force_remesh(realm, cpos)
	# Neighbour chunks may expose faces.
	if pos.x % ChunkData.CHUNK_X == 0:
		_force_remesh(realm, cpos + Vector2i(-1, 0))
	if pos.x % ChunkData.CHUNK_X == ChunkData.CHUNK_X - 1:
		_force_remesh(realm, cpos + Vector2i(1, 0))
	if pos.z % ChunkData.CHUNK_Z == 0:
		_force_remesh(realm, cpos + Vector2i(0, -1))
	if pos.z % ChunkData.CHUNK_Z == ChunkData.CHUNK_Z - 1:
		_force_remesh(realm, cpos + Vector2i(0, 1))
	# Vertically adjacent chunks share the column height; heights change with edits
	# only below y<CHUNK_Y (single 256 chunk). No cross-chunk vertical splits.


func _force_remesh(realm: int, cpos: Vector2i) -> void:
	if not has_chunk_data(realm, cpos):
		return
	chunk_data[realm][cpos].meshed = false
	var mesh_root: Node3D = chunk_nodes[realm].get(cpos)
	if mesh_root != null:
		var mi := mesh_root.get_node_or_null("Mesh")
		if mi != null:
			mi.free()
		var body := mesh_root.get_node_or_null("Body")
		if body != null:
			body.free()
	_try_mesh_chunk(realm, cpos)


## ---- Sand/gravel falling (discrete per-column solver) ----

func _update_falling(delta: float) -> void:
	_fall_timer += delta
	if _fall_timer < _fall_interval:
		return
	_fall_timer = 0.0
	var player := get_tree().get_first_node_in_group("player")
	if player == null or not is_instance_valid(player):
		return
	var center := ChunkData.to_chunk(Vector3i(floori(player.global_position.x), 0, floori(player.global_position.z)))
	for dx in range(-1, 2):
		for dz in range(-1, 2):
			_solve_falling_in_chunk(active_realm, center + Vector2i(dx, dz))


func _solve_falling_in_chunk(realm: int, cpos: Vector2i) -> void:
	if not has_chunk_data(realm, cpos):
		return
	var data: ChunkData = chunk_data[realm][cpos]
	var moved := false
	for lx in ChunkData.CHUNK_X:
		for lz in ChunkData.CHUNK_Z:
			for y in range(1, ChunkData.CHUNK_Y):
				var id := data.get_block(lx, y, lz)
				if not BlockRegistry.is_gravity(id):
					continue
				var below := data.get_block(lx, y - 1, lz)
				if below != BlockRegistry.Block.AIR and not BlockRegistry.is_fluid(below):
					continue
				if data.get_meta(lx, y, lz) == 1:
					continue
				# Move down one step this tick; try again next tick for the rest.
				data.set_block(lx, y, lz, BlockRegistry.Block.AIR)
				data.set_block(lx, y - 1, lz, id)
				data.set_meta(lx, y - 1, lz, 1)
				moved = true
	if moved:
		data.meshed = false
		data.dirty = true
		_force_remesh(realm, cpos)


## ---- Realm travel & environment ----

func set_active_realm(realm: int) -> void:
	if not REALMS.has(realm):
		return
	active_realm = realm
	PhysicsServer3D.area_set_param(get_viewport().find_world_3d() if false else null, 0, 0.0)  # no-op guard
	var meta := REALMS[realm]
	# Update the WorldEnvironment via the main scene when present.
	var env := get_tree().get_first_node_in_group("world_env")
	if env != null and env.has_method("apply_realm"):
		env.apply_realm(realm)
	var world3d := get_viewport().find_world_3d()
	if world3d != null:
		var phys: bool = PhysicsServer3D.get_process_info(PhysicsServer3D.INFO_ACTIVE_OBJECTS) != null
		pass


func switch_player_realm(player: Node, to_realm: int, target_pos: Vector3) -> void:
	set_active_realm(to_realm)
	if player != null and is_instance_valid(player):
		player.global_position = target_pos
		player.call("on_realm_changed", to_realm)


func ambient_temperature(realm: int, gy: int) -> float:
	var meta := realm_meta(realm)
	var t := meta.base_temp
	if realm == WorldGenerator.Realm.OVERWORLD:
		# Temperature drop per 2.2 m of altitude.
		t -= (float(gy) - 40.0) * 0.9
		t += sin(time_of_day * TAU) * 3.0
	return t


func wind_strength(realm: int, gy: int) -> float:
	var n := generator_for(realm).biome_gen.hilliness(floori(Time.get_ticks_msec() * 0.01), gy)
	return clampf(0.5 + n * 0.6 + float(gy) * 0.004, 0.3, 1.5)


func is_raining() -> bool:
	return realm_meta(active_realm).day_length > 0.0 and time_of_day > 0.62 and time_of_day < 0.8","filePath":"/home/work/voxel_survival/scripts/world/world_manager.gd"}

