{"content":"extends Node
## RecipeDB - autoload. Central recipe list for crafting / smelting / forging.
## Every recipe is exact on inputs and outputs (mass conservation).
## Forge recipes additionally require a temperature threshold; electric machines
## consume energy, manual work consumes stamina (both enforced at runtime).

## recipe shape:
## { "id", "name", "cat": "craft"|"smelt"|"forge", "station": "none"|"forge"|"forge_electric",
##   "inputs": {ItemIds.Item.X: count}, "outputs": {ItemIds.Item.Y: count},
##   "energy_kj": float, "temp_c": float }

var recipes: Array[Dictionary] = []


func _ready() -> void:
	_add({
		"id": "planks", "name": "Planks", "cat": "craft", "station": "none",
		"inputs": {ItemIds.Item.OAK_LOG: 1}, "outputs": {ItemIds.Item.PLANKS: 4}, "energy_kj": 0.0,
	})
	_add({
		"id": "stick", "name": "Sticks", "cat": "craft", "station": "none",
		"inputs": {ItemIds.Item.PLANKS: 1}, "outputs": {ItemIds.Item.STICK: 4}, "energy_kj": 0.0,
	})
	_add({
		"id": "pickaxe_wood", "name": "Wooden Pickaxe", "cat": "craft", "station": "none",
		"inputs": {ItemIds.Item.PLANKS: 3, ItemIds.Item.STICK: 2}, "outputs": {ItemIds.Item.TOOL_PICKAXE_WOOD: 1}, "energy_kj": 0.0,
	})
