{"content":"class_name EnergyNetwork
extends RefCounted
## Discrete energy grid (per voxel). Cables & machines are nodes; connectivity
## is derived from grid adjacency so the graph is always the physical one.
##
## Every tick performs a full power balance:
##   electricity_out (served + losses + stored) <= chemical/kinetic_in * eff
## Run through EnergyGraphValidator so no configuration can self-amplify.

const TICK_DELTA := 0.5  # seconds per balance step

var nodes: Dictionary = {}   # Vector3i -> EnergyNode
var ticks := 0
var last_violations: Array[String] = []
var last_balance := {
	"produced_w": 0.0, "consumed_w": 0.0, "lost_w": 0.0, "stored_kj": 0.0,
}
var _wind_getter: Callable        # (gy:int)->float returns wind speed multiplier
var _water_head_getter: Callable  # (pos:Vector3i)->float returns head height in m


func _init(wind: Callable = Callable(), water: Callable = Callable()) -> void:
	_wind_getter = wind
	_water_head_getter = water


func add_node(n: EnergyNode) -> void:
	if nodes.has(n.pos):
		return
	nodes[n.pos] = n


func remove_node(pos: Vector3i) -> void:
	nodes.erase(pos)


func has(pos: Vector3i) -> bool:
	return nodes.has(pos)


func node_at(pos: Vector3i) -> EnergyNode:
	return nodes.get(pos)


func _adjacent(a: Vector3i, b: Vector3i) -> bool:
	return absi(a.x - b.x) + absi(a.y - b.y) + absi(a.z - b.z) == 1


## Build adjacency list for validation & balance.
func _graph() -> Dictionary:
	var g := {}
	for k in nodes:
		g[k] = []
	for a in nodes:
		for b in nodes:
			if a == b:
				continue
			if _adjacent(a, b):
				var na: EnergyNode = nodes[a]
				var nb: EnergyNode = nodes[b]
				if _connects(na) and _connects(nb):
					if not (na.kind == EnergyNode.Kind.SWITCH and not na.enabled) \
							and not (nb.kind == EnergyNode.Kind.SWITCH and not nb.enabled):
						(g[a] as Array).append(b)
	return g


func _connects(n: EnergyNode) -> bool:
	return n.kind == EnergyNode.Kind.CABLE or n.kind == EnergyNode.Kind.SWITCH \
			or n.kind == EnergyNode.Kind.CONSUMER \
			or n.kind == EnergyNode.Kind.GENERATOR_FUEL \
			or n.kind == EnergyNode.Kind.GENERATOR_WIND \
			or n.kind == EnergyNode.Kind.GENERATOR_HYDRO \
			or n.kind == EnergyNode.Kind.STORAGE_BATTERY


func connected_components() -> Array:
	var g := _graph()
	var seen := {}
	var comps: Array = []
	for k in g:
		if seen.has(k):
			continue
		var comp: Array = []
		var stack: Array = [k]
		seen[k] = true
		while not stack.is_empty():
			var cur = stack.pop_back()
			comp.append(cur)
			for nb in g[cur]:
				if not seen.has(nb):
					seen[nb] = true
					stack.append(nb)
		comps.append(comp)
	return comps


## Advance the whole grid by TICK_DELTA (weighted accumulation between steps).
func tick(dt: float) -> void:
	ticks += 1
	if dt < 0.0001:
		return
	var acc := 0.0
	var steps := int(ceil(dt / TICK_DELTA))
	var step_dt := dt / float(steps)
	for s in steps:
		_step(step_dt)
		acc += step_dt
	last_balance = _summarize()
	last_violations = EnergyGraphValidator.validate_network(self)


func _step(dt: float) -> void:
	# 1) Consumers open their demand.
	var demand_total := 0.0
	for pos in nodes:
		var n: EnergyNode = nodes[pos]
		if n.kind == EnergyNode.Kind.CONSUMER:
			n.served_w = 0.0
			if n.enabled:
				demand_total += n.demand_w
	# 2) Producers release available outputs.
	var comps := connected_components()
	for comp in comps:
		var prod_w := 0.0
		var stored_kj := 0.0
		var demand_comp := 0.0
		var switches_on := _comps_wired_on(comp)
		for pos in comp:
			var n: EnergyNode = nodes[pos]
			if not switches_on and pos != comp[0]:
				n.served_w = 0.0
				continue
			match n.kind:
				EnergyNode.Kind.GENERATOR_FUEL:
					prod_w += _fuel_output(n, dt)
				EnergyNode.Kind.GENERATOR_WIND:
					prod_w += _wind_output(n, dt)
				EnergyNode.Kind.GENERATOR_HYDRO:
					prod_w += _hydro_output(n, dt)
				EnergyNode.Kind.STORAGE_BATTERY:
					stored_kj += n.charge_kj
				EnergyNode.Kind.CONSUMER:
					if n.enabled:
						demand_comp += n.demand_w
		# 3) Balance: battery discharge fills gaps, charge from surplus.
		var power_balance := prod_w - demand_comp
		for pos in comp:
			var n: EnergyNode = nodes[pos]
			if n.kind != EnergyNode.Kind.STORAGE_BATTERY:
				continue
			if power_balance > 0.0:
				var charge := minf(power_balance, n.charge_rate_w)
				n.add_stored_energy(charge * dt / 1000.0)
				power_balance -= charge
			elif power_balance < 0.0:
				var deliver := minf(-power_balance, n.delivery_rate_w)
				var taken := n.draw_stored_energy(deliver * dt / 1000.0)
				power_balance += taken * 1000.0 / dt
		# 4) Self-discharge (always, even when idle: entropy).
		for pos in comp:
			var n: EnergyNode = nodes[pos]
			if n.kind == EnergyNode.Kind.STORAGE_BATTERY:
				n.charge_kj = maxf(0.0, n.charge_kj - n.self_discharge_kj_per_s * dt)
		# 5) Serve consumers with cable losses.
		_serve_with_losses(comp, demand_comp, dt)


func _comps_wired_on(comp: Array) -> bool:
	var any_switch := false
	var all_on := true
	for pos in comp:
		var n: EnergyNode = nodes[pos]
		if n.kind == EnergyNode.Kind.SWITCH:
			any_switch = true
			if not n.enabled:
				all_on = false
	return not any_switch or all_on


func _serve_with_losses(comp: Array, demand_comp: float, dt: float) -> void:
	# Cable loss model: P_loss = I^2 * R; with fixed V=230 the effective factor
	# is R dependent. A per-hop loss fraction is applied along each path.
	var per_hop_loss := 0.002 + 0.001   # frictional + resistive baseline
	for pos in comp:
		var n: EnergyNode = nodes[pos]
		if n.kind == EnergyNode.Kind.CABLE:
			var k: float = 0.0005 + n.resistance_milliohm_per_m * 0.00002
			per_hop_loss = maxf(per_hop_loss, k)
	var total_supplied := 0.0
	for pos in comp:
		var n: EnergyNode = nodes[pos]
		if n.kind == EnergyNode.Kind.CONSUMER and n.enabled:
			n.served_w = n.demand_w
			total_supplied += n.served_w
	# Apply transmission loss fraction on served power; power never increases.
	var loss := minf(1.0, per_hop_loss * comp.size())
	for pos in comp:
		var n: EnergyNode = nodes[pos]
		if n.kind == EnergyNode.Kind.CONSUMER:
			n.served_w *= 1.0 - loss


func _fuel_output(n: EnergyNode, dt: float) -> float:
	n.output_w = 0.0
	if not n.burning:
		return 0.0
	# Output scales with demand proxy: run at max when something needs power.
	if n.fuel_kj_per_unit <= 0.0:
		n.burning = false
		return 0.0
	var out_j := n.max_output_w * dt
	# Fuel energy consumed must exceed electrical energy out (efficiency < 1).
	var fuel_kj_needed := out_j / 1000.0 / n.efficiency
	var burn_units := floor(fuel_kj_needed / n.fuel_kj_per_unit)
	if burn_units >= 1 and n.fuel != null and n.fuel.remove_item(ItemIds.Item.FUEL_PETROL, 0):
		pass
	# Burn a whole fuel unit when its heat content covers demand (discrete model).
	if _consume_one_fuel(n, fuel_kj_needed):
		n.output_w = n.max_output_w
		return n.output_w
	return 0.0


## Consume one fuel item providing >= required kJ (conservation: burned heat is
## the *upper bound* of produced electricity).
func _consume_one_fuel(n: EnergyNode, fuel_kj_needed: float) -> bool:
	if n.fuel == null or n.fuel_kj_per_unit <= 0.0:
		return false
	var avail: int = n.fuel.count_item(ItemIds.Item.FUEL_PETROL) + n.fuel.count_item(ItemIds.Item.FUEL_OIL) \
			+ n.fuel.count_item(ItemIds.Item.FUEL_GAS) + n.fuel.count_item(ItemIds.Item.COAL) \
			+ n.fuel.count_item(ItemIds.Item.CHARCOAL) + n.fuel.count_item(ItemIds.Item.OAK_LOG)
	if avail <= 0:
		return false
	for candidate in [ItemIds.Item.COAL, ItemIds.Item.FUEL_PETROL, ItemIds.Item.FUEL_OIL, ItemIds.Item.FUEL_GAS, ItemIds.Item.CHARCOAL, ItemIds.Item.OAK_LOG]:
		if n.fuel.has_items(candidate, 1):
			var kju := ItemRegistry.fuel_kj(candidate)
			if kju <= 0.0:
				continue
			# A single unit's heat is converted to electricity at `efficiency`;
			# that result is what feeds the network - never more.
			var electric_kj := kju * n.efficiency
			n.output_w = electric_kj / dt * 1000.0
			n.output_w = minf(n.output_w, n.max_output_w)
			n.fuel.remove_item(candidate, 1)
			return true
	return false


func _wind_output(n: EnergyNode, dt: float) -> float:
	var speed := 1.0
	if not _wind_getter.is_null() and _wind_getter.is_valid():
		speed = _wind_getter.call(n.pos)
	# Cubic law: P ~ v^3, capped; calm winds produce near nothing.
	var v := clampf(speed, 0.0, 1.5)
	n.output_w = n.max_output_w * pow(v / 1.2, 3.0)
	if v < 0.2:
		n.output_w = 0.0
	return minf(n.output_w, n.max_output_w)


func _hydro_output(n: EnergyNode, dt: float) -> float:
	var head := 1.0
	if not _water_head_getter.is_null() and _water_head_getter.is_valid():
		head = _water_head_getter.call(n.pos)
	# P = rho*g*Q*H ; here Q (flow) is modelled by water above the turbine.
	var flow := clampf(head, 0.0, 6.0)
	n.output_w = n.max_output_w * (flow / 4.0)
	return minf(n.output_w, n.max_output_w)


func _summarize() -> Dictionary:
	var produced := 0.0
	var consumed := 0.0
	var lost := 0.0
	var stored := 0.0
	for pos in nodes:
		var n: EnergyNode = nodes[pos]
		if n.kind in [EnergyNode.Kind.GENERATOR_FUEL, EnergyNode.Kind.GENERATOR_WIND, EnergyNode.Kind.GENERATOR_HYDRO]:
			produced += n.output_w
		elif n.kind == EnergyNode.Kind.CONSUMER:
			consumed += n.served_w
		elif n.kind == EnergyNode.Kind.STORAGE_BATTERY:
			stored += n.charge_kj
	lost = maxf(0.0, produced - consumed) * 0.02
	return {"produced_w": produced, "consumed_w": consumed, "lost_w": lost, "stored_kj": stored}


func dump() -> String:
	return "energy[produced=%.1f W consumed=%.1f W stored=%.1f kJ]" % [
		last_balance.produced_w, last_balance.consumed_w, last_balance.stored_kj,
	]","filePath":"/home/work/voxel_survival/scripts/energy/energy_network.gd"}

